# פרק 4 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=4
TITLE='קשר סיבתי עובדתי ומשפטי'
SUM=[' <p>היסוד המקשר בין ההתרשלות לנזק, מעוגן ב<strong>סעיף 64</strong> לפקודה ("אשם"), שפורש כדורש שני סוגי קשר.</p> <h3>4.1 קשר סיבתי עובדתי</h3> <p>מבחן ה<strong>"אלמלא"</strong> (but-for): אלמלא התנהגות המזיק, האם הנזק היה מתרחש? אם הנזק היה קורה בכל מקרה — אין קשר עובדתי.</p> <h3>4.2 קשר סיבתי משפטי — סעיף 64(2)</h3> <p>מסנן מבין הגורמים העובדתיים את אלה שראוי להטיל בגינם אחריות. <strong>סעיף 64(2)</strong> מציב מבחן גמיש עם שלוש חלופות: <strong>הצפיות</strong> (האם המזיק צריך היה לצפות את הנזק), <strong>הסיכון</strong> (האם הנזק בתחום הסיכון שיצרה ההתנהגות), ו<strong>השכל הישר</strong> (קשר הגיוני-טבעי).</p> <h3>4.3 ניתוק הקשר</h3> <p>לפי <strong>סעיף 64(2)</strong>, לא יראו אשם כגורם לנזק אם "אשמו של אדם אחר הוא שהיה הסיבה המכרעת" — גורם זר מתערב מנתק את הקשר.</p> <h3>4.4 נקודות מפתח למבחן</h3> <ul><li>עובדתי = מבחן ה"אלמלא".</li><li>משפטי (ס׳ 64(2)) = צפיות / סיכון / שכל ישר.</li><li>גורם זר מתערב מנתק את הקשר.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 64 לפקודת הנזיקין — אשם וקשר סיבתי", '', 'דרישת הקשר הסיבתי פורשה כדורשת קשר עובדתי (מבחן ה"אלמלא") וקשר משפטי כאחד.'), ("ס' 64(2) — מבחני הקשר המשפטי", '', 'מבחן גמיש בעל שלוש חלופות: צפיות, סיכון ושכל ישר; "אשמו של אחר כסיבה מכרעת" מנתק את הקשר.'), ('מבחן ה"אלמלא"', '', 'הכלי לקביעת סיבתיות עובדתית: אלמלא התנהגות המזיק, האם הנזק היה מתרחש.'), ('ע״א 576/81 בן שמעון נ׳ ברדה', 'נערים פרצו למחסן נשק שלא אובטח כראוי, נטלו נשק, ובמהלך משחק (״רולטה רוסית״) נורה אחד מהם ומת. נדונה אחריות מי שהתרשל בשמירה על המחסן.', 'נקבע שהליך הגרימה צריך להיות צפוי רק בקווים כלליים — ברמת הפשטה גבוהה — ואין צורך לצפות את פרטי ההשתלשלות. דרישה לצפות כל פרט הייתה מרוקנת את מבחן הצפיות מתוכן.'), ('ע״א 8199/01 עזבון מירו נ׳ מירו', 'שוטר השאיר את נשקו הטעון בבית חברים; אחד הנוכחים נטל אותו, התעסק בו וירה למוות בבן דודו.', 'הקשר הסיבתי לא נותק: התכונות הרשלניות של ההתערבות היו צפויות למי שמשאיר נשק טעון. גורם מתערב שולל את הקשר רק כשתכונותיו אינן ניתנות לצפייה — המבחן הוא צפיות ולא חומרת אשמו של המתערב.'), ('ע״א 2714/02 פלונית נ׳ מרכז רפואי בני ציון', 'בשל הערכה רשלנית של משקל העובר הוחלט שלא לבצע ניתוח קיסרי; ימים ספורים לאחר מכן מת העובר כתוצאה מכריכת חבל הטבור.', 'אף שעובדתית ניתוח היה מונע את המוות, נשלל הקשר הסיבתי המשפטי: הסיכון שבגללו מבצעים קיסרי לעובר כבד הוא סיבוך בלידה, לא חנק מחבל הטבור. הנזק שהתממש לא היה הנזק שבגללו ההתנהגות רשלנית.'), ('ע״א 231/84 קופת חולים של ההסתדרות נ׳ פאתח, פ״ד מב(3) 312 (1988)', 'דיון בתביעת רשלנות רפואית שבה לא ניתן היה להוכיח במאזן הסתברויות שהטיפול הנאות היה מונע את הנזק, אלא רק שהרשלנות שללה סיכוי להחלמה.', 'נקבע שהסיכוי שאבד הוא נזק בר-פיצוי, והפיצוי נגזר משיעור הסיכוי. זו ההכרה הראשונה בישראל בפיצוי יחסי כזה.'), ('דנ״א 4693/05 בית חולים כרמל – חיפה נ׳ מלול', 'עיכוב רשלני בניתוח קיסרי, כשלא היה ברור אם נזקו של התינוק נבע מהעיכוב או מגורמים אחרים. בערעור נפסק פיצוי של 20% לפי תרומה הסתברותית.', 'בדיון הנוסף נדחתה אחריות יחסית ככלל וכלל מאזן ההסתברויות נשמר, ופסק הדין בערעור בוטל (אך התובעים לא נדרשו להשיב את מה ששולם להם). הדעות התפצלו; עלה חריג אפשרי של ״הטיה נשנית״ — מזיק שכלל ״הכול או כלום״ פוטר באופן שיטתי מול קבוצת ניזוקים.'), ('ע״א 3900/14 דנינו נ׳ המרכז הרפואי הלל יפה', 'רשלנות בניתוח בלוטת התריס שגרמה לפגיעה בבלוטות יותרת התריס; הערכאה הדיונית פסקה פיצוי של 50% בגין אובדן סיכוי.', 'נקבע שכאשר הסיכוי שאבד עולה על 50% הניזוק עמד בנטל במאזן ההסתברויות וזכאי לפיצוי מלא; פיצוי יחסי שמור למקרים שהסיכוי נמוך מ-50%. ההחלה הא-סימטרית מעדיפה את הניזוק.'), ('ע״א 285/86 נגר נ׳ וילנסקי', 'דיון בתביעת רשלנות שבה התנהגות הנתבע פגעה ביכולתו של התובע להוכיח את הקשר הסיבתי.', 'בפסק הדין הופיע לראשונה המונח ״נזק ראייתי״: כשהנתבע בהתרשלותו שלל מהתובע את האפשרות להוכיח את עילתו, נטל השכנוע עובר אליו. הדוקטרינה שומרת על כלל ״הכול או כלום״ ורק הופכת את הצד הנושא בספק.')]
QS=[{'q': 'לפי ס׳ 64 לפקודת הנזיקין, מתי רואים אדם כמי שגרם לנזק באשמו?', 'o': ['אם האשם הגביר במידה כלשהי את הסיכון לנזק, גם בלי שגרם לו', 'רק אם האשם היה הסיבה העיקרית לנזק', 'אם האשם היה הסיבה או אחת הסיבות לנזק', 'רק אם האשם היה הסיבה היחידה לנזק'], 'c': 2, 'e': 'נכון. זו לשון הרישא של ס׳ 64: ״הסיבה או אחת הסיבות לנזק״, ולכן די בכך שהאשם הוא אחד הגורמים.'}, {'q': 'מהו המבחן המרכזי לקשר סיבתי עובדתי?', 'o': ['מבחן הסיכון', 'מבחן הצפיות', 'מבחן השכל הישר', 'מבחן ״הסיבה בלעדיה אין״'], 'c': 3, 'e': 'נכון. שואלים אם אלמלא התנהגות הנתבע הנזק היה נמנע; זו שאלה עובדתית.'}, {'q': 'כיצד מפעילים את מבחן האלמלא במקרה של מחדל?', 'o': ['מניחים שהנזק היה נמנע, והנטל עובר תמיד לנתבע', 'במחדל אין צורך בקשר סיבתי כלל', 'מוסיפים בדמיון את הפעולה שהייתה צריכה להיעשות ושואלים אם היא הייתה מונעת את הנזק', 'בודקים רק אם המחדל היה רשלני'], 'c': 2, 'e': 'נכון. במחדל הניתוח היפותטי: מה היה קורה אילו הנתבע היה פועל כנדרש — למשל מציב שלט או מבצע בדיקה.'}, {'q': 'מה רמת ההוכחה הנדרשת מהתובע לגבי קשר סיבתי עובדתי, ומה תוצאתה?', 'o': ['ראיות ברורות ומשכנעות; פיצוי לפי שיעור השכנוע', 'די בראשית ראיה, והנטל עובר לנתבע', 'מעבר לספק סביר; מי שלא הוכיח כך מקבל פיצוי חלקי', 'מאזן הסתברויות; ככלל ״הכול או כלום״'], 'c': 3, 'e': 'נכון. די במעל 50%; ככלל מי שעובר את הרף זוכה בפיצוי מלא ומי שלא — אינו זוכה כלל, והחריגים (אובדן סיכוי, הטיה נשנית) מצומצמים.'}, {'q': 'אילו שלושה מבחני עזר גיבשה הפסיקה לקשר הסיבתי המשפטי?', 'o': ['צפיות, ישירות ומטרה', 'אלמלא, דיות, ונתח שוק', 'צפיות, סיכון ושכל ישר', 'סבירות, מידתיות ותום לב'], 'c': 2, 'e': 'נכון. אלה שלושת המבחנים; בפועל הצפיות מיושם ברשלנות, הסיכון באחריות חמורה, והשכל הישר מלווה כמבחן שלילי.'}, {'q': 'לפי הלכת בן שמעון נ׳ ברדה, מה צריך המזיק לצפות כדי שיתקיים מבחן הצפיות?', 'o': ['את היקף הנזק המדויק', 'את כל פרטי ההשתלשלות שהביאה לנזק', 'את סוג הנזק ואת הליך הגרימה בקווים כלליים', 'את זהות הניזוק בשמו'], 'c': 2, 'e': 'נכון. נקבעה רמת הפשטה גבוהה: די בצפיות של קווי המתאר של הנזק והגרימה.'}, {'q': 'בעוולה של אחריות חמורה, איזה מבחן משמש בעיקר לקשר הסיבתי המשפטי?', 'o': ['מבחן הסיכון', 'מבחן האדם הסביר', 'מבחן ״הסיבה בלעדיה אין״', 'מבחן הצפיות'], 'c': 0, 'e': 'נכון. באחריות חמורה ומוחלטת (וגם בהפרת חובה חקוקה ובחוק הפיצויים לנפגעי תאונות דרכים) שואלים אם הנזק הוא מימוש הסיכון שההסדר נועד למנוע.'}, {'q': 'שוטר השאיר את נשקו הטעון על השולחן בבית חברים. אחד האורחים התעסק בנשק וירה בטעות באורח אחר. השוטר טוען שהאורח הוא ״גורם זר מתערב״. מה הדין?', 'o': ['הטענה נדחית, כי בנזיקין אין דוקטרינה של גורם מתערב', 'הטענה נדחית, כי התערבות כזו צפויה למי שמשאיר נשק טעון; השניים אחראים', 'הטענה מתקבלת, כי כל מעשה של אדם אחר קוטע את הקשר', 'הטענה מתקבלת, כי האורח פעל ברשלנות חמורה יותר'], 'c': 1, 'e': 'נכון. זו הלכת עזבון מירו: התכונות הרשלניות של ההתערבות היו צפויות, ולכן הקשר לא נותק; אחריות יחד ולחוד וחלוקה לפי ס׳ 84.'}, {'q': 'רופא העריך ברשלנות את משקל העובר ולכן לא בוצע ניתוח קיסרי. העובר מת מכריכת חבל הטבור — סיבוך שאינו קשור למשקל. מה הדין לפי הפסיקה?', 'o': ['אין קשר סיבתי עובדתי כלל', 'יש אחריות, כי ניתוח היה מונע את המוות ולכן מבחן האלמלא מתקיים', 'אין קשר סיבתי משפטי, כי הנזק שהתממש אינו הנזק שבגללו ההתנהגות רשלנית', 'יש אחריות מכוח נזק ראייתי'], 'c': 2, 'e': 'נכון. זו פרשת בני ציון: הסיכון שבגללו מבצעים קיסרי לעובר כבד הוא סיבוך בלידה, לא חנק מחבל הטבור.'}, {'q': 'רכבת נסעה מעל המהירות המותרת, ועץ רקוב נפל עליה ופגע בנוסע. ידוע שהמהירות לא החמירה את הפגיעה. מה הדין?', 'o': ['אין קשר עובדתי כלל', 'יש אחריות, כי אלמלא המהירות הרכבת לא הייתה שם', 'יש אחריות מוחלטת על נהג שעבר את המהירות', 'אין קשר משפטי, כי תרומת ההתרשלות היא של ״זמן ומקום״ בלבד ולא הגבירה את הסיכון'], 'c': 3, 'e': 'נכון. זו הדוגמה הקלאסית לחריג ״זמן ומקום״ במבחן השכל הישר: התכונה הרשלנית (מהירות) לא הגבירה סיכון לנפילת עצים.'}, {'q': 'מטופל הוכיח שהרשלנות באבחון שללה ממנו סיכוי של 35% להחלים. לפי הפסיקה, מה זכאותו?', 'o': ['פיצוי של 50%, כמחצית בשל ספק', 'פיצוי מלא, כי הוכחה רשלנות', 'לא כלום, כי לא הוכיח מעל 50%', 'פיצוי של כ-35% מהנזק בגין אובדן סיכויי החלמה'], 'c': 3, 'e': 'נכון. לפי הלכת פאתח הסיכוי שאבד הוא נזק בר-פיצוי, והפיצוי נגזר משיעורו כשהוא מתחת ל-50%.'}, {'q': 'מטופלת הוכיחה שהרשלנות שללה ממנה סיכוי של 70% להחלים. לפי ע״א 3900/14 דנינו, מה זכאותה?', 'o': ['אין פיצוי, כי אובדן סיכוי אינו ראש נזק', 'פיצוי של 30%', 'פיצוי של 70%', 'פיצוי מלא'], 'c': 3, 'e': 'נכון. כשהסיכוי שאבד עולה על 50% הניזוקה עמדה בנטל במאזן ההסתברויות, ולכן זכאית לפיצוי מלא — החלה א-סימטרית לטובת הניזוק.'}, {'q': 'מה קבע הדיון הנוסף בפרשת מלול (דנ״א 4693/05)?', 'o': ['שאחריות יחסית אינה הכלל, וכלל מאזן ההסתברויות נשמר, עם חריג אפשרי של ״הטיה נשנית״', 'שיש לבטל את דוקטרינת הנזק הראייתי', 'שאין להכיר בשום מקרה בפיצוי יחסי', 'שאחריות יחסית לפי שיעור הגברת הסיכון היא הכלל בכל תביעת נזיקין'], 'c': 0, 'e': 'נכון. רוב השופטים דחו אחריות הסתברותית ככלל; נותר חריג אפשרי למזיק שכלל ״הכול או כלום״ פוטר באופן שיטתי מול קבוצת ניזוקים.'}, {'q': 'בית חולים לא שמר את תרשים המוניטור מהלידה, ולכן לא ניתן לדעת אם הצוות זיהה מצוקה עוברית בזמן. מה הדוקטרינה הרלוונטית ומה השפעתה?', 'o': ['גורם זר מתערב — הקשר נקטע', 'הסתכנות מרצון — התביעה נדחית', 'אובדן סיכויי החלמה — פיצוי יחסי', 'נזק ראייתי — נטל השכנוע לגבי הקשר הסיבתי עובר לבית החולים'], 'c': 3, 'e': 'נכון. הנתבע בהתרשלותו שלל מהתובעת את היכולת להוכיח (הלכת נגר); הנטל עובר אליו, וההכרעה נשארת ״הכול או כלום״.'}, {'q': 'מה הביקורת שהביע השופט עמית (בפרשת ששון) על ״נזק ראייתי מובנה״?', 'o': ['שהדוקטרינה צריכה לחול בכל תביעת רשלנות רפואית', 'שיש להעניק פיצוי עונשי במקרים כאלה', 'שכשההתרשלות עצמה היא שיוצרת את חוסר הוודאות ההיפותטי, החלה מכנית הופכת את הדוקטרינה לכלי להטלת אחריות', 'שהנטל צריך לעבור לתובע'], 'c': 2, 'e': 'נכון. כשהשאלה היא ״מה היה קורה אילו״ — לנתבע אין יכולת אמיתית להוכיח, והעברת הנטל שקולה לקבלת התביעה; לכן נדרשת זהירות וריסון.'}, {'q': 'נער קפץ למים רדודים בבריכה, שבה לא הוצב שלט אזהרה כנדרש בתקנות, ונפגע. באיזה מבחן משתמשים לקשר הסיבתי המשפטי ומה התוצאה?', 'o': ['מבחן השכל הישר — הנער אחראי, ולכן הקשר נקטע', 'מבחן נתח השוק — אחריות יחסית', 'מבחן הישירות — אין קשר כי הנזק עקיף', 'מבחן הסיכון — הנזק הוא בדיוק הסיכון שהשילוט נועד למנוע, ולכן יש קשר'], 'c': 3, 'e': 'נכון. כך בפרשת ועקנין: פגיעה בקפיצה למים רדודים היא בתוך מתחם הסיכון שהתקנות נועדו למנוע.'}, {'q': 'מה הייתה ״הגישה הישנה״ לגורם זר מתערב, ומה הגישה הנוהגת?', 'o': ['הישנה — מתערב בעל יסוד נפשי חמור יותר נחשב ״סיבה מכרעת״; הנוהגת — השאלה אם ההתערבות הייתה צפויה', 'הישנה — אחריות מוחלטת; הנוהגת — פטור', 'שתיהן זהות', 'הישנה — צפיות; הנוהגת — חומרת היסוד הנפשי'], 'c': 0, 'e': 'נכון. כיום גם מעשה מכוון או פלילי אינו קוטע את הקשר אם היה בתחום הצפייה הסבירה של הנתבע.'}, {'q': 'מה התוצאה המעשית כשנקבע שגורם זר מתערב אינו קוטע את הקשר הסיבתי?', 'o': ['רק הנתבע הראשון אחראי', 'שניהם אחראים כלפי הניזוק יחד ולחוד, ואחריותם הפנימית מתחלקת לפי ס׳ 84', 'האחריות מתחלקת שווה בשווה בכל מקרה', 'רק המתערב אחראי'], 'c': 1, 'e': 'נכון. ס׳ 11 מטיל אחריות יחד ולחוד על מעוולים, וס׳ 84 קובע השתתפות לפי ״הצדק והיושר״ ומידת האחריות.'}, {'q': 'מה קובע ס׳ 64(1) לפקודה?', 'o': ['שהנתבע אחראי לכל נזק טבע שקרה בשטחו', 'שאין אחריות לנזק שנגרם בכוח עליון כלשהו', 'שתאגיד אינו אחראי לנזקי טבע', 'שלא יראו אדם כגורם לנזק אם הנזק נגרם על ידי מקרה טבעי בלתי רגיל, שאדם סביר לא יכול היה לצפות ולמנוע אף בזהירות סבירה'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 64(1); בפועל החריג נדיר, ומשב רוח לא נדיר אינו נכלל בו.'}, {'q': 'לפי לשון ס׳ 64(2), מתי לא יראו אדם כמי שגרם לנזק באשמו?', 'o': ['כאשר אדם אחר היה רשלן גם הוא', 'כאשר הנזק היה גדול מהצפוי', 'כאשר הניזוק היה בגיר', 'כאשר אשמו של אדם אחר הוא שהיה הסיבה המכרעת לנזק'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 64(2); הפסיקה מפרשת ״סיבה מכרעת״ לפי מבחן הצפיות.'}, {'q': 'מהו מבחן הסיבתיות העובדתית?', 'o': ['הצפיות', 'מבחן ה"אלמלא"', 'הסיכון', 'השכל הישר'], 'c': 1, 'e': 'but-for.'}, {'q': 'היכן מעוגן הקשר הסיבתי?', 'o': ["ס' 35", "ס' 64", "ס' 76", "ס' 2"], 'c': 1, 'e': 'ס\' 64 — "אשם".'}, {'q': "אילו מבחנים קובע ס' 64(2) לקשר המשפטי?", 'o': ['אחד בלבד', 'צפיות/סיכון/שכל ישר', 'אלמלא', 'מידתיות'], 'c': 1, 'e': 'שלושה מבחנים חלופיים.'}, {'q': 'מה מנתק את הקשר הסיבתי?', 'o': ['אשם תורם', 'סיבה מכרעת של אדם אחר', 'נזק רחוק', 'הקטנת נזק'], 'c': 1, 'e': "גורם זר מתערב (ס' 64(2))."}, {'q': 'הקשר הסיבתי המשפטי נועד ל:', 'o': ['חשב פיצוי', 'לסנן גורמים שאין להטיל בגינם אחריות', 'להגדיר נזק', 'לחלק אשם'], 'c': 1, 'e': 'שיקולי מדיניות.'}]
